function slPrecision(){QA('#labFields input[type=range]').forEach(input=>{if(input.closest('.sl-number-wrap'))return;const wrap=document.createElement('div');wrap.className='sl-number-wrap';input.replaceWith(wrap);wrap.append(input);const number=document.createElement('input');number.type='number';for(const k of ['min','max','step','value'])number[k]=input[k];number.setAttribute('aria-label',(input.closest('label')?.querySelector('span')?.textContent||'Exact value').trim());number.oninput=()=>{if(!Number.isFinite(number.valueAsNumber))return;input.value=clamp(number.valueAsNumber,+input.min,+input.max);input.dispatchEvent(new Event('input',{bubbles:true}));number.value=input.value};input.addEventListener('input',()=>{number.value=input.value;const out=wrap.parentElement?.querySelector('output');if(out)out.textContent=Number(input.value).toFixed(input.step==='1'?0:2)});const reset=document.createElement('button');reset.type='button';reset.textContent='↺';reset.title='Reset this control';reset.onclick=()=>{slRemember();const key=input.dataset.labField||input.dataset.layerField;let baseline=input.dataset.layerField?makeLabLayer('Layer',labDraft.type,labDraft.palette):typeTune(defaultShell(labDraft.type,labDraft.palette));input.value=baseline[key]??input.min;input.dispatchEvent(new Event('input',{bubbles:true}))};wrap.append(number,reset)});QA('#labFields .group h3').forEach(h=>{const b=document.createElement('button');b.textContent='RESET SECTION';b.className='sl-section-reset';b.style.cssText='float:right;font-size:9px';b.onclick=()=>{slRemember();const group=h.closest('.group'),baseline=typeTune(defaultShell(labDraft.type,labDraft.palette));group.querySelectorAll('[data-lab-field]').forEach(input=>{const key=input.dataset.labField;if(baseline[key]!=null)labDraft[key]=structuredClone(baseline[key])});slChanged();renderLabFields()};h.append(b)})}
