function slSequenceFields(){const seq=labDraft.sequence;slStageIndex=clamp(slStageIndex,0,Math.max(0,seq.stages.length-1));return slSection('BURST SEQUENCE',`<div class="sl-properties">${slCheck('sequence.enabled','Use timed burst steps')}</div><div class="sl-row"><button data-sl="stage-add">ADD STEP</button><button data-sl="stage-duplicate">DUPLICATE</button><button data-sl="stage-delete">DELETE</button><button data-sl="stage-up">↑</button><button data-sl="stage-down">↓</button></div><div class="sl-sequence-lane" id="slSequenceLane">${seq.stages.map((s,i)=>`<button class="sl-stage-dot" data-stage-drag="${i}" style="left:${clamp(s.time/12*90,0,90)}%">${slText(s.name)} · ${(+s.time).toFixed(2)}s</button>`).join('')}</div>${seq.stages.map((s,i)=>`<div class="sl-row"><button data-stage-select="${i}" ${i===slStageIndex?'class="active"':''}>${i+1}</button><input data-stage-field="name" data-stage="${i}" value="${slText(s.name)}" class="sl-grow" aria-label="Step name"><input data-stage-field="time" data-stage="${i}" type="number" value="${s.time}" min="0" max="12" step=".01" aria-label="Step start time in seconds"><select data-stage-field="type" data-stage="${i}" aria-label="Step shape">${slOptions(SHELLS.map(s=>[s.id,s.name]),s.type)}</select><input type="checkbox" data-stage-field="enabled" data-stage="${i}" ${s.enabled!==false?'checked':''} aria-label="Enable step"></div>`).join('')}${seq.stages[slStageIndex]?slStageFields(seq.stages[slStageIndex],slStageIndex):'<div class="sl-note">Add a step to program a shell from its first bloom to its final sparks.</div>'}<div class="sl-note">Times are measured from the main burst. Drag stage blocks to set ignition time. Offsets are fractions of the burst area.</div>`)}
